import{_ as e,o,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Accounts and roles","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/administrateur/comptes-et-roles.md","filePath":"src/en/guide/administrateur/comptes-et-roles.md"}'),n={name:"en/guide/administrateur/comptes-et-roles.md"};function s(i,t,d,c,l,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="accounts-and-roles" tabindex="-1">Accounts and roles <a class="header-anchor" href="#accounts-and-roles" aria-label="Permalink to &quot;Accounts and roles&quot;">​</a></h1><p>The Administrator has access to the whole application. Their <strong>Administration</strong> section gathers the management of accounts, roles and settings.</p><h2 id="role-requests" tabindex="-1">Role requests <a class="header-anchor" href="#role-requests" aria-label="Permalink to &quot;Role requests&quot;">​</a></h2><p><strong>Administration → Role requests</strong> is the screen for people who approve roles; the Administrator can approve all of them, in addition to the actor designated for each, so that no request stays blocked by a vacant post.</p><table tabindex="0"><thead><tr><th>Role</th><th>Normally approved by</th></tr></thead><tbody><tr><td>Lead Trainer, Coach-Tutor</td><td>Pedagogical Coordinator</td></tr><tr><td>Admissions Advisor, Officers, Direction, Coordinator</td><td>Administrator</td></tr><tr><td>Funder</td><td>Partnerships Officer</td></tr><tr><td>Event funder</td><td>Events Officer</td></tr><tr><td>Project holder</td><td>Incubation Officer, when the project is retained</td></tr></tbody></table><p>The screen has:</p><ul><li><strong>Awaiting a decision</strong>: each request with the person&#39;s message. <strong>Approve</strong> activates the role at once and notifies the person by e-mail; <strong>Refuse</strong> requires a <strong>reason</strong>, sent by e-mail. A refusal does not touch the person&#39;s other roles;</li><li><strong>Holders</strong>: accounts with a role you approve, with the date and author of the approval, <strong>Withdraw</strong> (with a reason);</li><li><strong>Grant a role</strong> directly to an existing account, without a prior request.</li></ul><p>Nobody decides their <strong>own requests</strong> or withdraws <strong>their own role</strong>.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p><strong>Administration → Users</strong> lists accounts, which you search by name or e-mail, filter by role, and <strong>export as CSV</strong> (respecting the current search). For each: their roles, status, verification state and <strong>last sign-in</strong>.</p><ul><li><strong>New user</strong> creates an account, for example for a staff member, with their roles. At creation, you assign any role, even one that someone else normally approves. A new account cannot be a Funder, since it is an individual account.</li><li><strong>Edit</strong> updates the name, e-mail, phone (in international format) and, if you wish, the password; an empty field keeps the current one. Each change is <strong>logged</strong>. <strong>Manage roles</strong> leads to role requests.</li><li><strong>Delete</strong> removes the account for good. You cannot delete <strong>your own account</strong> from this panel.</li></ul><h3 id="account-statuses" tabindex="-1">Account statuses <a class="header-anchor" href="#account-statuses" aria-label="Permalink to &quot;Account statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>Normal account</td></tr><tr><td>Suspended</td><td>Non-payment after D+30: no paid action, whatever the module, and no more access to Sève. Payment restores everything</td></tr><tr><td>Canopé</td><td>Former certified learner</td></tr><tr><td>Deactivated</td><td>Inactive for a year: data is kept and the account reactivates at the next sign-in</td></tr></tbody></table><h2 id="organization-accounts" tabindex="-1">Organization accounts <a class="header-anchor" href="#organization-accounts" aria-label="Permalink to &quot;Organization accounts&quot;">​</a></h2><p><strong>Administration → Organization accounts</strong> lists requests to convert an individual account into an organization account, for <strong>the Administrator alone</strong>.</p><ul><li><strong>Awaiting a decision</strong>: the account, the company name requested, the <strong>supporting document</strong> (company registration or equivalent, to download), the person&#39;s message.</li><li><strong>Approve</strong>: the account takes the company name as its <strong>name</strong>, the <strong>old name is kept</strong> in the request and in the log, and the person is notified. Their history stays readable, read-only.</li><li><strong>Refuse</strong>: a <strong>reason</strong> is mandatory, sent by e-mail; the account stays unchanged and can ask again.</li></ul><p>You do not decide your own request. An account that already has a request in progress cannot submit a second, and an organization account cannot ask again.</p>',17)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
